38	/* Analog register block (SYS_ANA_REG0 = 0x44010100, REGn = +4*n). */
39	
40	#define ANA_SPI_STATE      0x440100E8u
41	#define ANA_REG0           0x44010100u
42	#define ANA_REG2           0x44010108u
43	#define ANA_REG3           0x4401010Cu
44	#define ANA_REG5           0x44010114u
45	#define ANA_REG8           0x44010120u
46	#define ANA_REG9           0x44010124u
47	#define ANA_REG10          0x44010128u
48	#define ANA_REG11          0x4401012Cu
49	#define ANA_REG12          0x44010130u
50	#define ANA_REG13          0x44010134u
51	#define ANA_REG25          0x44010164u
52	
53	#define EN_DPLL_BIT        (1u << 5)
54	
55	/* Analog-SPI busy-wait timeout (iterations).  Sized so that even at the
56	 * slowest cold-start clock (26 MHz) a genuine SPI transfer completes
57	 * well within the budget, but a stuck state machine aborts in < 1 ms.
58	 */
59	
