101	/*
102	 * Analog register write helpers.  Every write to an ANA_REG triggers an
103	 * internal analog-SPI transfer; the SPI busy bit in ANA_SPI_STATE[idx]
104	 * (idx = register number) must clear before the next write or it is lost.
105	 * Mirrors sys_ll_set_analog_reg_value (sys_ll.h:51-59).
106	 *
107	 * All helpers return 0 on success, -1 on SPI-busy timeout.
108	 */
109	
110	static int ana_wait(uint32_t addr)
111	{
112	    uint32_t idx = (addr - ANA_REG0) >> 2;
113	    uint32_t t = ANA_SPI_TIMEOUT;
114	
115	    while (REG32(ANA_SPI_STATE) & (1u << idx))
116	        if (--t == 0)
117	            return -1;
118	    return 0;
119	}
120	
121	static int ana_write(uint32_t addr, uint32_t val)
122	{
123	    REG32(addr) = val;
124	    return ana_wait(addr);
125	}
126	
127	static int ana_or(uint32_t addr, uint32_t bits)
128	{
129	    REG32(addr) = REG32(addr) | bits;
130	    return ana_wait(addr);
131	}
132	
133	static int ana_and(uint32_t addr, uint32_t mask)
134	{
135	    REG32(addr) = REG32(addr) & mask;
136	    return ana_wait(addr);
137	}
138	
139	static int ana_rmw(uint32_t addr, uint32_t clear, uint32_t set)
140	{
141	    REG32(addr) = (REG32(addr) & ~clear) | set;
142	    return ana_wait(addr);
143	}
