145	/* ------------------------------------------------------------------ */
146	/* DPLL SPI recalibration (sys_hal_cali_dpll, sys_hal.c:2659-2696).   */
147	/* Returns 0 on success, -1 on SPI timeout.                           */
148	/* ------------------------------------------------------------------ */
149	
150	static int boot_cali_dpll(void)
151	{
152	    /* Lower the SPI trigger and settle. */
153	
154	    if (ana_and(ANA_REG0, ~(1u << 19)) < 0)   /* spitrig = 0 */
155	        return -1;
156	    clk_delay(120);
157	
158	    /* Rising edge starts recalibration; gate unlock-detect during settle. */
159	
160	    if (ana_rmw(ANA_REG0, (1u << 4), (1u << 19)) < 0)  /* spitrig=1, spideten=0 */
161	        return -1;
162	    clk_delay(3400);
163	
164	    /* Re-enable detect (the SDK's de-facto "lock wait"). */
165	
166	    if (ana_or(ANA_REG0, (1u << 4)) < 0)      /* spideten = 1 */
167	        return -1;
168	    clk_delay(3400);
169	
170	    return 0;
171	}
