173	/* ------------------------------------------------------------------ */
174	/* Step functions — each returns 0 on success, -1 on failure.         */
175	/* ------------------------------------------------------------------ */
176	
177	static int step1_dpll_power(void)
178	{
179	    /* ANA_REG5: power up audpll briefly, enable DPLL + DCO, set adc_div,
180	     * re-power-down audpll. */
181	
182	    uint32_t v = REG32(ANA_REG5);
183	    v &= ~(1u << 13);                              /* PWDAUDPLL = 0 */
184	    v |= (1u << 5) | (1u << 3) | (1u << 2);       /* EN_DPLL | NC_3_3 | EN_DCO */
185	    if (ana_write(ANA_REG5, v) < 0) return -1;
186	    if (ana_rmw(ANA_REG5, (0x3u << 10), (0x1u << 10)) < 0) return -1;  /* adc_div */
187	    if (ana_or(ANA_REG5, (1u << 13)) < 0) return -1;  /* PWDAUDPLL = 1 */
188	    return 0;
189	}
190	
191	static int step2_band_dsptrig(void)
192	{
193	    /* ANA_REG0: band field, safe-mode replacement, dsptrig pulse. */
194	
195	    if (ana_or(ANA_REG0, (0x13u << 20)) < 0) return -1;   /* band = 0x13 */
196	    if (ana_write(ANA_REG0, 0xF1305B56u) < 0) return -1;  /* dpll_tsten=0 */
197	    if (ana_or(ANA_REG0, (1u << 26)) < 0) return -1;      /* dsptrig = 1 */
198	    if (ana_and(ANA_REG0, ~(1u << 26)) < 0) return -1;    /* dsptrig = 0 */
199	    return 0;
200	}
