203	{
204	    /* ANA_REG2/3: xtal tuning and bias. */
205	
206	    if (ana_write(ANA_REG2, 0x7E003450u) < 0) return -1;  /* xtal ctune=0x50 */
207	    if (ana_write(ANA_REG3, 0xC5F00B88u) < 0) return -1;
208	    return 0;
209	}
