212	{
213	    /* spi_latch1v on -> ANA_REG8/9/10-13/25 (default branch for MP_C) ->
214	     * ANA_REG3.inbufen0v9 -> latch off. */
215	
216	    if (ana_or(ANA_REG9, (1u << 9)) < 0) return -1;       /* spi_latch1v = 1 */
217	    if (ana_write(ANA_REG8,  0x57E62F26u) < 0) return -1;
218	    if (ana_write(ANA_REG9,  0x787BC8A4u) < 0) return -1;
219	    if (ana_write(ANA_REG10, 0xC3D543A7u) < 0) return -1;
220	    if (ana_write(ANA_REG11, 0xB47E99F8u) < 0) return -1;
221	    if (ana_write(ANA_REG12, 0xB47ECF20u) < 0) return -1;
222	    if (ana_write(ANA_REG13, 0x727070EEu) < 0) return -1;
223	    if (ana_write(ANA_REG25, 0x0961FAA4u) < 0) return -1;
224	    if (ana_or(ANA_REG3, (1u << 6)) < 0) return -1;       /* inbufen0v9 = 1 */
225	    if (ana_and(ANA_REG9, ~(1u << 9)) < 0) return -1;     /* spi_latch1v = 0 */
