235	/* ------------------------------------------------------------------ */
236	/* Public: cold-start DPLL enable.                                    */
237	/*                                                                    */
238	/* Called from c_main() after UART init, before the FAL partition     */
239	/* scan.  Bounded and fail-safe: if any analog-SPI write times out,   */
240	/* the remaining sequence is aborted and control returns to c_main;   */
241	/* the app's 26 MHz fallback handles EN_DPLL=0.                       */
242	/* ------------------------------------------------------------------ */
243	
244	void boot_clock_cold_init(void)
245	{
246	    /* Guard: skip if DPLL already enabled (soft-reset / loader residue). */
247	
248	    if (REG32(ANA_REG5) & EN_DPLL_BIT)
249	        return;
250	
251	    /* Run the cold-init sequence.  Abort on any SPI-write timeout. */
252	
253	    if (step1_dpll_power() < 0 ||
254	        step2_band_dsptrig() < 0 ||
255	        step3_xtal_bias() < 0 ||
256	        step4_latched_block() < 0 ||
257	        step5_recalibrate() < 0)
258	    {
259	        clk_puts("BClk FAIL\r\n");
260	        return;
261	    }
262	
263	    /* Evidence: confirm EN_DPLL landed. */
264	
265	    clk_puts("BClk A5=");
266	    clk_puthex(REG32(ANA_REG5));
267	    clk_puts(" A9=");
268	    clk_puthex(REG32(ANA_REG9));
269	    clk_puts("\r\n");
270	}

1	/*
2	 * boot_main.c - BK7258 Tier-1 bootloader C main.
3	 *
4	 *   uint32_t c_main(void);
5	 *
6	 * Responsibilities (Tier-1 features I / A, with J handled by start.S):
7	 *   I  UART1 logging of boot progress.
8	 *   A  FAL partition table parse -> locate "app", derive its logical address.
9	 *      App header validation (MSP / Reset Thumb / "BK7236\0\0" magic).
10	 * On success c_main prints "jump to:0x02010000\r\n", "JMP\r\n" and returns
11	 * the app logical vector address (e.g. 0x02010000). On failure it prints
12	 * "BAD\r\n" plus a short reason and loops forever (never returns).
13	 *
14	 * The app logical address equals FLASH_BASE + partition.offset, so the same
15	 * scan works if the table is later moved to a real flash partition.
16	 *
17	 * Freestanding: no libc, no mutable globals -> no .bss zeroing needed by
18	 * c_main (start.S calls c_main directly without a C runtime startup).
19	 */
20	
21	#include <stdint.h>
