/****************************************************************************
 * Private: DPLL re-recalibration at the raised core voltage
 ****************************************************************************/

static void bk7258_recal_dpll_at_vdd(void)
{
  /* Re-trigger the DPLL SPI recalibration now that VDDIG is at the 320 MHz
   * tier (0xE).  The bootloader calibrated the DPLL at the default low
   * voltage (0xB), where it could not acquire a 480 MHz lock; that tuning
   * does not auto-update when the voltage is raised, so the recalibration
   * must be re-run at the operating voltage.  Mirrors the bootloader's
   * boot_cali_dpll / SDK sys_hal_cali_dpll: a spitrig pulse with the
   * unlock-detect gate cleared during settle, two settle delays.  Every
   * ANA_REG0 write drains through the analog-SPI busy bit[0].
   */

  BK7258_REG(BK7258_ANA_REG0) &= ~BK7258_ANA0_SPITRIG;            /* spitrig = 0 */
  bk7258_ana_wait(0);
  bk7258_clk_sleep_us(BK7258_DPLL_TRIG_DELAY_US);

  BK7258_REG(BK7258_ANA_REG0) =
      (BK7258_REG(BK7258_ANA_REG0) & ~BK7258_ANA0_SPIDETEN) | BK7258_ANA0_SPITRIG;
  bk7258_ana_wait(0);
  bk7258_clk_sleep_us(BK7258_DPLL_CAL_DELAY_US);

  BK7258_REG(BK7258_ANA_REG0) |= BK7258_ANA0_SPIDETEN;            /* spideten = 1 */
  bk7258_ana_wait(0);
  bk7258_clk_sleep_us(BK7258_DPLL_CAL_DELAY_US);
}

